cards.solution:
public class Main {
    public static void main(String[] args) {
        try {
            cekSaldo(5000);
        } catch (IllegalArgumentException e) {
            System.out.println(e.getMessage());
        }
    }

    static void cekSaldo(int saldo) {
        if (saldo < 10000) {
            throw new IllegalArgumentException("Saldo kurang");
        }
    }
}
